import Testing
@testable import RemoteCore

// Vectors generated with Python's arbitrary-precision integers and hashlib, using the
// same SRP formulas (see SRPClient) and an independently computed server side
// (S = (A·v^u)^b), so they check both the big-integer arithmetic and the transcript.

private func bytes(_ hex: String) -> [UInt8] { BigUInt(hex: hex)!.bytes }
private func bytes(_ hex: String, _ width: Int) -> [UInt8] { BigUInt(hex: hex)!.bytes(width: width) }

@Test func srpClientMatchesReferenceTranscript() throws {
    let salt = bytes("390c8c7d7247342cd8100f2f6f770d65", 16)
    let a = bytes("d670e58e0351d8ae8e4f6eac342fc231b7b08716eb3fc12896b9622317749428", 32)
    let B = bytes("", 384)
    let srp = try SRPClient(password: "1234", salt: salt, serverPublicKey: B, privateKey: a)
    #expect(srp.publicKey == bytes("", 384))
    #expect(srp.sessionKey == bytes("a52b691c9caeebdbecd7e5a652dd8e987e25c6b69b408920118d8f9336d155260620e1b3b4872b72ccebd1fd576910d5f485789b43e9d78b3b53838070055a63", 64))
    #expect(srp.proof == bytes("8b3574706aea31f59d87cf023e84e32f1ff73fe4305baf726bbae1749042e7fe8e083a3e99d38ff7604a264ddca5d2969d9f3f7ce7f21d8061770fb4d49b2384", 64))
    #expect(srp.verify(serverProof: bytes("94400620930b9fa06132f4492dc95dcaadcca441d7512a5c137a9ca1d448032d901d8e7e4e19e6dedaba56c6d0d44277d8444bac9e9abf753118f8756cba08e3", 64)))
    #expect(!srp.verify(serverProof: [UInt8](repeating: 0, count: 64)))
}

@Test func srpRejectsWrongPin() throws {
    let srp = try SRPClient(password: "1235", salt: bytes("390c8c7d7247342cd8100f2f6f770d65", 16), serverPublicKey: bytes("", 384), privateKey: bytes("d670e58e0351d8ae8e4f6eac342fc231b7b08716eb3fc12896b9622317749428", 32))
    #expect(!srp.verify(serverProof: bytes("94400620930b9fa06132f4492dc95dcaadcca441d7512a5c137a9ca1d448032d901d8e7e4e19e6dedaba56c6d0d44277d8444bac9e9abf753118f8756cba08e3", 64)))
}

@Test func srpRejectsZeroAndOversizedServerKey() {
    #expect(throws: ProtocolError.self) { try SRPClient(password: "1", salt: [1], serverPublicKey: [0], privateKey: [1]) }
    #expect(throws: ProtocolError.self) { try SRPClient(password: "1", salt: [1], serverPublicKey: SRPClient.N.bytes, privateKey: [1]) }
}

@Test func montgomeryPowMatchesReference() {
    let m = Montgomery(modulus: SRPClient.N)
    #expect(m.pow(BigUInt(hex: "")!, BigUInt(hex: "9477f26144b98289fcd59a54a7bb1fee08f571242425051c1ccd17f9acae01f5057ca02135e92b1d3f28ede0d7ac3baea9e13deef86ab1031d0f646e1f40a097c976bf46c697d2caf82eeeacbe226e875555790f82ec1d3fcff2a3af4d46b0a18e8830e07bc1e398f1012bd4acefaecbd389be4bcfc49b64a0872e6cc3ababced2057ee05cde00902c7")!) == BigUInt(hex: "")!)
    #expect(m.pow(BigUInt(hex: "")!, BigUInt(hex: "99c570dc1951c2442f9298cb3a570ccec313571810afc132d0d113db17d30cbc97d0fef792866836886a260cd0b7b45145c1a81682c64e50cad66237a0465e7e4236472f1a38f2c6ec8cc4169a3ae3a2b7fdfe01893f3aed0b6c7ac1491def88334e647cb8f74e69a5d0dd27a65bd628881ad1b72dba7abe1c29e1a8ef4f341e07a83f73f16dbf4a8b2")!) == BigUInt(hex: "")!)
    #expect(m.pow(BigUInt(hex: "")!, BigUInt(hex: "3455675f6ad325b55dd785729763a12917c1a26f88938703800149e259b5d58c705f979d04af47aebdd597a1ecffcf00fecb91ee9e5efe09f07cefe2a1f727d83495822cb77f4de2c089aea6429b1491e243192b7044259405278e4b98d4787f93bca44eb860726e25cfd56a926076b3e36bb2313f55b06258e7e26f36a8483f8b8332dd3313a0b9965")!) == BigUInt(hex: "")!)
    #expect(m.pow(BigUInt(7), BigUInt(0)) == BigUInt(1))
    #expect(m.pow(BigUInt(7), BigUInt(1)) == BigUInt(7))
}

@Test func montgomeryMulModMatchesReference() {
    let m = Montgomery(modulus: SRPClient.N)
    #expect(m.mulMod(BigUInt(hex: "")!, BigUInt(hex: "")!) == BigUInt(hex: "")!)
    #expect(m.mulMod(BigUInt(hex: "")!, BigUInt(hex: "")!) == BigUInt(hex: "")!)
}

@Test func bigUIntBasics() {
    let x = BigUInt(hex: "ffffffffffffffffff")!
    #expect(x.bytes == [UInt8](repeating: 0xFF, count: 9))
    #expect((x + BigUInt(1)).bytes == [1] + [UInt8](repeating: 0, count: 9))
    #expect((x - x).isZero)
    #expect((BigUInt(0xFFFF_FFFF_FFFF_FFFF) * BigUInt(0xFFFF_FFFF_FFFF_FFFF)) == BigUInt(hex: "fffffffffffffffe0000000000000001")!)
    #expect(BigUInt(bytes: [0, 0, 1, 2]).bytes == [1, 2])
    #expect(BigUInt(bytes: [1, 2]).bytes(width: 4) == [0, 0, 1, 2])
    #expect(BigUInt(0).bitWidth == 0)
    #expect(BigUInt(5).bitWidth == 3)
}
